def compare_versions(a: str, b: str) -> int:
    def parse_version(version_str: str):
        # Split build metadata (everything after +)
        if '+' in version_str:
            version_str = version_str.split('+')[0]

        # Split pre-release (everything after -)
        if '-' in version_str:
            main_part, prerelease_part = version_str.split('-', 1)
            prerelease = prerelease_part.split('.')
        else:
            main_part = version_str
            prerelease = None

        # Parse major.minor.patch
        parts = main_part.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return (major, minor, patch, prerelease)

    def parse_prerelease_identifier(identifier: str):
        # Returns (is_numeric, value) where numeric identifiers are compared as int
        # and non-numeric as string. Numeric identifiers have lower precedence.
        if identifier.isdigit():
            return (0, int(identifier))
        else:
            return (1, identifier)

    major_a, minor_a, patch_a, prerelease_a = parse_version(a)
    major_b, minor_b, patch_b, prerelease_b = parse_version(b)

    # Compare major.minor.patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release versions
    # No pre-release has higher precedence than with pre-release
    if prerelease_a is None and prerelease_b is None:
        return 0
    if prerelease_a is None:
        return 1
    if prerelease_b is None:
        return -1

    # Compare pre-release identifiers one by one
    for i in range(max(len(prerelease_a), len(prerelease_b))):
        if i >= len(prerelease_a):
            # a has fewer identifiers, so a < b
            return -1
        if i >= len(prerelease_b):
            # b has fewer identifiers, so a > b
            return 1

        id_a = parse_prerelease_identifier(prerelease_a[i])
        id_b = parse_prerelease_identifier(prerelease_b[i])

        if id_a != id_b:
            return -1 if id_a < id_b else 1

    return 0

