from solution import compare_versions


def test_basic_numeric():
    assert compare_versions('1.2.10', '1.2.9') == 1
    assert compare_versions('1.2.9', '1.2.10') == -1
    assert compare_versions('2.0.0', '1.9.9') == 1
    assert compare_versions('1.10.0', '1.9.0') == 1


def test_equal():
    assert compare_versions('1.2.3', '1.2.3') == 0


def test_prerelease_lower():
    assert compare_versions('1.0.0-alpha', '1.0.0') == -1
    assert compare_versions('1.0.0', '1.0.0-alpha') == 1


def test_spec_chain():
    chain = ['1.0.0-alpha', '1.0.0-alpha.1', '1.0.0-alpha.beta', '1.0.0-beta',
             '1.0.0-beta.2', '1.0.0-beta.11', '1.0.0-rc.1', '1.0.0']
    for i in range(len(chain)):
        for j in range(len(chain)):
            exp = (i > j) - (i < j)
            assert compare_versions(chain[i], chain[j]) == exp


def test_build_ignored():
    assert compare_versions('1.0.0+a', '1.0.0+b') == 0
    assert compare_versions('1.0.0+build', '1.0.0') == 0
    assert compare_versions('1.0.0-alpha+x', '1.0.0-alpha+y') == 0
    assert compare_versions('1.0.0-alpha+1-2', '1.0.0-alpha') == 0


def test_hyphen_in_identifier():
    assert compare_versions('1.0.0-alpha-1', '1.0.0-alpha-2') == -1
    assert compare_versions('1.0.0-a-b', '1.0.0-a-b') == 0


def test_ascii_order():
    assert compare_versions('1.0.0-Z', '1.0.0-a') == -1
    assert compare_versions('1.0.0-a', '1.0.0-Z') == 1


def test_numeric_vs_alnum():
    assert compare_versions('1.0.0-1', '1.0.0-a') == -1
    assert compare_versions('1.0.0-2a', '1.0.0-10') == 1


def test_numeric_compare():
    assert compare_versions('1.0.0-2', '1.0.0-10') == -1


def test_more_identifiers():
    assert compare_versions('1.0.0-a.1', '1.0.0-a') == 1
    assert compare_versions('1.0.0-a', '1.0.0-a.1') == -1


def test_unicode_digit():
    # '²' is not an ASCII digit; treated as non-numeric alnum string
    assert compare_versions('1.0.0-²', '1.0.0-1') == 1

